/*
# Progress-Generated Posts

## Summary

Creates the `progress_posts` table and database triggers that auto-generate
social posts when members complete coaching actions — finishing a commitment,
completing a plan step, hitting a milestone, or completing a goal. This is the
"action is the content" principle: posts are generated by doing, not writing.

## New Tables

### `progress_posts`
- `id` (uuid, PK)
- `user_id` (uuid, references auth.users) — the member who earned the achievement
- `post_type` (text) — one of: commitment_completed, plan_step_completed,
  goal_completed, milestone_achieved, streak_milestone
- `title` (text) — auto-generated headline
- `body` (text, nullable) — auto-generated description
- `ref_target_type` (text) — the source table: coaching_commitments, coach_plan_steps, etc.
- `ref_target_id` (uuid) — the ID of the source row
- `goal_id` (uuid, nullable) — linked goal for filtering by shared goals
- `like_count` (int, default 0) — denormalized
- `comment_count` (int, default 0) — denormalized
- `is_auto_generated` (boolean, default true) — always true for these posts
- `created_at` (timestamptz)

## Triggers

- `trg_post_on_commitment_completed` — AFTER UPDATE on `coaching_commitments`:
  when status changes TO 'completed', inserts a progress_post (only if the
  user's member profile is public).
- `trg_post_on_plan_step_completed` — AFTER UPDATE on `coach_plan_steps`:
  when status changes TO 'completed', inserts a progress_post.
- `trg_post_on_milestone` — AFTER INSERT on `milestone_achievements`:
  inserts a progress_post for new milestones.
- `trg_post_on_goal_completed` — AFTER UPDATE on `user_goals`:
  when status changes TO 'completed', inserts a progress_post.

All trigger functions check whether the user has a public member profile
(is_public = true) before inserting. If the profile is private, no post is
created — the achievement stays private.

## Security

- RLS enabled on `progress_posts`.
- SELECT: any authenticated user can see posts from public profiles
  (the post must belong to a user whose member_profiles.is_public = true).
  Users can always see their own posts.
- INSERT: only the trigger functions (SECURITY DEFINER) can insert — no
  direct client INSERT.
- UPDATE: owner only, but only like_count/comment_count are not client-writable
  (managed by Phase 4 triggers). Client can't UPDATE at all — only triggers write.
- DELETE: owner only.

## Important Notes

1. Posts are only created for users with public profiles. Private users' achievements
   stay private — no opt-out needed, it's opt-in via the profile.
2. Duplicate prevention: each trigger checks whether a post already exists for the
   same (ref_target_type, ref_target_id, post_type) before inserting, so re-saving
   a completed commitment won't create duplicate posts.
3. The `goal_id` on progress posts enables filtering the feed by shared goals.
*/

-- ============================================================
-- 1. progress_posts table
-- ============================================================

CREATE TABLE IF NOT EXISTS public.progress_posts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  post_type text NOT NULL,
  title text NOT NULL,
  body text,
  ref_target_type text NOT NULL,
  ref_target_id uuid NOT NULL,
  goal_id uuid,
  like_count int NOT NULL DEFAULT 0,
  comment_count int NOT NULL DEFAULT 0,
  is_auto_generated boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.progress_posts ENABLE ROW LEVEL SECURITY;

-- SELECT: own posts OR posts from public profiles
DROP POLICY IF EXISTS "select_own_progress_posts" ON public.progress_posts;
CREATE POLICY "select_own_progress_posts"
ON public.progress_posts FOR SELECT
TO authenticated
USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "select_public_progress_posts" ON public.progress_posts;
CREATE POLICY "select_public_progress_posts"
ON public.progress_posts FOR SELECT
TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM public.member_profiles mp
    WHERE mp.user_id = progress_posts.user_id
    AND mp.is_public = true
  )
);

-- No INSERT/UPDATE policy for clients — only SECURITY DEFINER triggers write.
-- DELETE: owner only
DROP POLICY IF EXISTS "delete_own_progress_posts" ON public.progress_posts;
CREATE POLICY "delete_own_progress_posts"
ON public.progress_posts FOR DELETE
TO authenticated
USING (auth.uid() = user_id);

-- Indexes
CREATE INDEX IF NOT EXISTS idx_progress_posts_user ON public.progress_posts (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_progress_posts_goal ON public.progress_posts (goal_id) WHERE goal_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_progress_posts_created ON public.progress_posts (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_progress_posts_ref ON public.progress_posts (ref_target_type, ref_target_id);

-- ============================================================
-- 2. Helper: check if user has a public profile
-- ============================================================

CREATE OR REPLACE FUNCTION public.has_public_profile(p_user_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE(
    (SELECT is_public FROM public.member_profiles WHERE user_id = p_user_id),
    false
  );
$$;

-- ============================================================
-- 3. Helper: check for duplicate post
-- ============================================================

CREATE OR REPLACE FUNCTION public.post_exists_for_target(
  p_user_id uuid,
  p_ref_target_type text,
  p_ref_target_id uuid,
  p_post_type text
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.progress_posts
    WHERE user_id = p_user_id
    AND ref_target_type = p_ref_target_type
    AND ref_target_id = p_ref_target_id
    AND post_type = p_post_type
  );
$$;

-- ============================================================
-- 4. Trigger: commitment completed
-- ============================================================

CREATE OR REPLACE FUNCTION public.create_post_on_commitment_completed()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_goal_id uuid;
  v_title text;
BEGIN
  -- Only fire when status transitions TO completed
  IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN
    -- Skip if user doesn't have a public profile
    IF NOT public.has_public_profile(NEW.user_id) THEN
      RETURN NEW;
    END IF;

    -- Skip duplicates
    IF public.post_exists_for_target(NEW.user_id, 'coaching_commitments', NEW.id, 'commitment_completed') THEN
      RETURN NEW;
    END IF;

    v_goal_id := NEW.goal_id;
    v_title := 'Completed a commitment';

    -- Try to get the goal title for a richer post
    IF v_goal_id IS NOT NULL THEN
      SELECT title INTO v_title FROM public.user_goals WHERE id = v_goal_id;
      IF v_title IS NOT NULL THEN
        v_title := 'Kept a commitment: ' || v_title;
      END IF;
    END IF;

    INSERT INTO public.progress_posts (user_id, post_type, title, body, ref_target_type, ref_target_id, goal_id)
    VALUES (
      NEW.user_id,
      'commitment_completed',
      v_title,
      NEW.description,
      'coaching_commitments',
      NEW.id,
      v_goal_id
    );
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_post_on_commitment_completed ON public.coaching_commitments;
CREATE TRIGGER trg_post_on_commitment_completed
AFTER UPDATE ON public.coaching_commitments
FOR EACH ROW EXECUTE FUNCTION public.create_post_on_commitment_completed();

-- ============================================================
-- 5. Trigger: plan step completed
-- ============================================================

CREATE OR REPLACE FUNCTION public.create_post_on_plan_step_completed()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id uuid;
  v_goal_id uuid;
  v_plan_title text;
BEGIN
  IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN
    -- Get the user_id from the plan
    SELECT p.user_id, p.title INTO v_user_id, v_plan_title
    FROM public.coach_plans p WHERE p.id = NEW.plan_id;

    IF v_user_id IS NULL THEN RETURN NEW; END IF;

    IF NOT public.has_public_profile(v_user_id) THEN
      RETURN NEW;
    END IF;

    IF public.post_exists_for_target(v_user_id, 'coach_plan_steps', NEW.id, 'plan_step_completed') THEN
      RETURN NEW;
    END IF;

    -- Get goal_id from linked commitment if available
    IF NEW.commitment_id IS NOT NULL THEN
      SELECT goal_id INTO v_goal_id FROM public.coaching_commitments WHERE id = NEW.commitment_id;
    END IF;

    INSERT INTO public.progress_posts (user_id, post_type, title, body, ref_target_type, ref_target_id, goal_id)
    VALUES (
      v_user_id,
      'plan_step_completed',
      'Completed a plan step: ' || COALESCE(NEW.user_set_title, NEW.coach_proposed_title, NEW.title),
      COALESCE(v_plan_title, '') || ' — Step ' || NEW.order_index + 1,
      'coach_plan_steps',
      NEW.id,
      v_goal_id
    );
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_post_on_plan_step_completed ON public.coach_plan_steps;
CREATE TRIGGER trg_post_on_plan_step_completed
AFTER UPDATE ON public.coach_plan_steps
FOR EACH ROW EXECUTE FUNCTION public.create_post_on_plan_step_completed();

-- ============================================================
-- 6. Trigger: milestone achieved
-- ============================================================

CREATE OR REPLACE FUNCTION public.create_post_on_milestone()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.has_public_profile(NEW.user_id) THEN
    RETURN NEW;
  END IF;

  IF public.post_exists_for_target(NEW.user_id, 'milestone_achievements', NEW.id, 'milestone_achieved') THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.progress_posts (user_id, post_type, title, body, ref_target_type, ref_target_id)
  VALUES (
    NEW.user_id,
    'milestone_achieved',
    COALESCE(NEW.achievement_name, 'Milestone unlocked'),
    COALESCE(NEW.achievement_description, NEW.celebration_message)
  );
END;
$$;

DROP TRIGGER IF EXISTS trg_post_on_milestone ON public.milestone_achievements;
CREATE TRIGGER trg_post_on_milestone
AFTER INSERT ON public.milestone_achievements
FOR EACH ROW EXECUTE FUNCTION public.create_post_on_milestone();

-- ============================================================
-- 7. Trigger: goal completed
-- ============================================================

CREATE OR REPLACE FUNCTION public.create_post_on_goal_completed()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN
    IF NOT public.has_public_profile(NEW.user_id) THEN
      RETURN NEW;
    END IF;

    IF public.post_exists_for_target(NEW.user_id, 'user_goals', NEW.id, 'goal_completed') THEN
      RETURN NEW;
    END IF;

    INSERT INTO public.progress_posts (user_id, post_type, title, body, ref_target_type, ref_target_id, goal_id)
    VALUES (
      NEW.user_id,
      'goal_completed',
      'Completed a goal: ' || NEW.title,
      NEW.notes,
      'user_goals',
      NEW.id,
      NEW.id
    );
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_post_on_goal_completed ON public.user_goals;
CREATE TRIGGER trg_post_on_goal_completed
AFTER UPDATE ON public.user_goals
FOR EACH ROW EXECUTE FUNCTION public.create_post_on_goal_completed();
